68	  input                                   din_valid_in_4,
69	  input       [DIN_DATA_WIDTH-1:0]        din_data_4,
70	  output                                  din_enable_5,
71	  output                                  din_valid_5,
72	  input                                   din_valid_in_5,
73	  input       [DIN_DATA_WIDTH-1:0]        din_data_5,
74	  output                                  din_enable_6,
75	  output                                  din_valid_6,
76	  input                                   din_valid_in_6,
77	  input       [DIN_DATA_WIDTH-1:0]        din_data_6,
78	  output                                  din_enable_7,
79	  output                                  din_valid_7,
80	  input                                   din_valid_in_7,
81	  input       [DIN_DATA_WIDTH-1:0]        din_data_7,
82	  input                                   din_unf,
83	
84	  // d-out interface
85	
86	  input                                   dout_rst,
87	  input                                   dout_clk,
88	  input                                   dout_enable_0,
89	  input                                   dout_valid_0,
90	  output                                  dout_valid_out_0,
91	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_0,
92	  input                                   dout_enable_1,
93	  input                                   dout_valid_1,
94	  output                                  dout_valid_out_1,
95	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_1,
96	  input                                   dout_enable_2,
97	  input                                   dout_valid_2,
98	  output                                  dout_valid_out_2,
99	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_2,
100	  input                                   dout_enable_3,
101	  input                                   dout_valid_3,
102	  output                                  dout_valid_out_3,
103	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_3,
104	  input                                   dout_enable_4,
105	  input                                   dout_valid_4,
106	  output                                  dout_valid_out_4,
107	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_4,
108	  input                                   dout_enable_5,
109	  input                                   dout_valid_5,
110	  output                                  dout_valid_out_5,
111	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_5,
112	  input                                   dout_enable_6,
113	  input                                   dout_valid_6,
114	  output                                  dout_valid_out_6,
115	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_6,
116	  input                                   dout_enable_7,
117	  input                                   dout_valid_7,
118	  output                                  dout_valid_out_7,
119	  output      [DOUT_DATA_WIDTH-1:0]       dout_data_7,
120	  output  reg                             dout_unf
121	);
122	
123	  localparam  M_MEM_RATIO = DOUT_DATA_WIDTH/DIN_DATA_WIDTH;
124	  localparam  ADDRESS_WIDTH = (DIN_ADDRESS_WIDTH > 5) ? DIN_ADDRESS_WIDTH : 5;
125	  localparam  DATA_WIDTH = DOUT_DATA_WIDTH * NUM_OF_CHANNELS;
126	  localparam  T_DIN_DATA_WIDTH = DIN_DATA_WIDTH * 8;
127	  localparam  T_DOUT_DATA_WIDTH = DOUT_DATA_WIDTH * 8;
128	
129	  // internal registers
130	
131	  reg         [(DATA_WIDTH-1):0]          din_wdata = 'd0;
132	  reg         [(ADDRESS_WIDTH-1):0]       din_waddr = 'hc;
133	  reg                                     din_wr = 'd0;
134	  reg                                     din_valid = 'd0;
135	  reg         [ 6:0]                      din_req_cnt = 'd0;
136	  reg         [ 7:0]                      din_enable_m1 = 'd0;
137	  reg         [ 7:0]                      din_enable = 'd0;
138	  reg                                     din_req_t_m1 = 'd0;
139	  reg                                     din_req_t_m2 = 'd0;
140	  reg                                     din_req_t_m3 = 'd0;
141	  reg                                     din_req = 'd0;
142	  reg                                     din_init = 'd0;
143	  reg                                     din_unf_d = 'd0;
144	  reg         [ 7:0]                      dout_valid = 'd0;
145	  reg         [(T_DOUT_DATA_WIDTH+1):0]   dout_data = 'd0;
146	  reg         [(DATA_WIDTH-1):0]          dout_rdata = 'd0;
147	  reg         [ 7:0]                      dout_enable = 'd0;
148	  reg                                     dout_req_t = 'd0;
149	  reg                                     dout_init = 'd0;
150	  reg         [(ADDRESS_WIDTH-1):0]       dout_raddr = 'd0;
151	  reg                                     dout_unf_m1 = 'd0;
152	
153	  // internal signals
154	
155	  wire        [(T_DIN_DATA_WIDTH-1):0]    din_data_s;
156	  wire                                    din_req_s;
157	  wire        [ 7:0]                      dout_enable_s;
158	  wire        [ 7:0]                      dout_valid_s;
159	  wire        [(T_DOUT_DATA_WIDTH+1):0]   dout_data_s;
160	  wire                                    dout_init_s;
161	  wire        [(DATA_WIDTH-1):0]          dout_rdata_s;
162	  wire        [ 2:0]                      din_wcnt_s;
163	
164	  // variables
165	
166	  // enables & valids
167	
168	  assign din_enable_7 = din_enable[7];
169	  assign din_enable_6 = din_enable[6];
170	  assign din_enable_5 = din_enable[5];
171	  assign din_enable_4 = din_enable[4];
172	  assign din_enable_3 = din_enable[3];
173	  assign din_enable_2 = din_enable[2];
174	  assign din_enable_1 = din_enable[1];
175	  assign din_enable_0 = din_enable[0];
176	
177	  assign din_valid_7 = din_valid;
178	  assign din_valid_6 = din_valid;
179	  assign din_valid_5 = din_valid;
180	  assign din_valid_4 = din_valid;
181	  assign din_valid_3 = din_valid;
182	  assign din_valid_2 = din_valid;
183	  assign din_valid_1 = din_valid;
184	  assign din_valid_0 = din_valid;
185	
186	  assign din_data_s = {din_data_7, din_data_6, din_data_5, din_data_4,
187	    din_data_3, din_data_2, din_data_1, din_data_0};
188	
189	  // simple data transfer-- no ovf/unf handling- read-bw > write-bw
190	  // dout_width >= din_width only
191	
192	  genvar n;
193	  generate
194	  for (n = 0; n < NUM_OF_CHANNELS; n = n + 1) begin: g_in
195	  if (M_MEM_RATIO == 1) begin
196	  always @(posedge din_clk) begin
197	    if (din_valid_in_0 == 1'b1) begin
198	      din_wdata[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)] <=
199	        din_data_s[((DIN_DATA_WIDTH*(n+1))-1):(DIN_DATA_WIDTH*n)];
200	    end
201	  end
202	  end else begin
203	  always @(posedge din_clk) begin
204	    if (din_valid_in_0 == 1'b1) begin
205	      din_wdata[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)] <=
206	        {din_data_s[((DIN_DATA_WIDTH*(n+1))-1):(DIN_DATA_WIDTH*n)],
207	        din_wdata[((DOUT_DATA_WIDTH*(n+1))-1):(DIN_DATA_WIDTH+(DOUT_DATA_WIDTH*n))]};
208	    end
209	  end
210	  end
211	  end
212	  endgenerate
213	
214	  generate
215	  if (M_MEM_RATIO == 1) begin
216	    assign din_wcnt_s = 'b0;
217	  end else begin
218	    reg [ 2:0] din_wcnt = 'd0;
219	
220	    always @(posedge din_clk or negedge din_rstn)
221	    if (din_rstn == 1'b0) begin
222	      din_wcnt <= 'd0;
223	    end else begin
224	      if (din_valid_in_0 == 1'b1) begin
225	        din_wcnt <= din_wcnt + 1'b1;
226	      end
227	    end
228	
229	    assign din_wcnt_s = din_wcnt;
230	  end
231	  endgenerate
232	
233	  always @(posedge din_clk or negedge din_rstn) begin
234	    if (din_rstn == 1'b0) begin
235	      din_waddr <= 'hc;
236	      din_wr <= 1'd0;
237	    end else begin
238	      if ((din_req == 1'b1) && (din_init == 1'b1)) begin
239	        din_waddr <= 'h18;
240	      end else if (din_wr == 1'b1) begin
241	        din_waddr <= din_waddr + 1'b1;
242	      end
243	     case (M_MEM_RATIO)
244	        8: din_wr <= din_valid_in_0 & din_wcnt_s[2] & din_wcnt_s[1] & din_wcnt_s[0];
245	        4: din_wr <= din_valid_in_0 & din_wcnt_s[1] & din_wcnt_s[0];
246	        2: din_wr <= din_valid_in_0 & din_wcnt_s[0];
247	        default: din_wr <= din_valid_in_0;
248	      endcase
249	    end
250	  end
251	
252	  always @(posedge din_clk or negedge din_rstn) begin
253	    if (din_rstn == 1'b0) begin
254	      din_valid <= 'd0;
255	      din_req_cnt <= 'd0;
256	    end else begin
257	      din_valid <= din_req_cnt[6];
258	      if (din_req_s == 1'b1) begin
259	        case (M_MEM_RATIO)
260	          8: din_req_cnt <= 7'h40;
261	          4: din_req_cnt <= 7'h60;
262	          2: din_req_cnt <= 7'h70;
263	          default: din_req_cnt <= 7'h78;
264	        endcase
265	      end else if (din_req_cnt[6] == 1'b1) begin
266	        din_req_cnt <= din_req_cnt + 1'b1;
267	      end
268	    end
269	  end
270	
271	  assign din_req_s = din_req_t_m3 ^ din_req_t_m2;
272	
273	  always @(posedge din_clk or negedge din_rstn) begin
274	    if (din_rstn == 1'b0) begin
275	      din_enable_m1 <= 'd0;
276	      din_enable <= 'd0;
277	      din_req_t_m1 <= 'd0;
278	      din_req_t_m2 <= 'd0;
279	      din_req_t_m3 <= 'd0;
280	      din_req <= 'd0;
281	      din_init <= 'd0;
282	      din_unf_d <= 'd0;
283	    end else begin
284	      din_enable_m1 <= dout_enable;
285	      din_enable <= din_enable_m1;
286	      din_req_t_m1 <= dout_req_t;
287	      din_req_t_m2 <= din_req_t_m1;
288	      din_req_t_m3 <= din_req_t_m2;
289	      din_req <= din_req_s;
290	      if (din_req_s == 1'b1) begin
291	        din_init <= dout_init;
292	      end
293	      din_unf_d <= din_unf;
294	    end
295	  end
296	
297	  // read interface (bus expansion and/or clock conversion)
298	
299	  assign dout_enable_s = {dout_enable_7, dout_enable_6, dout_enable_5, dout_enable_4,
300	    dout_enable_3, dout_enable_2, dout_enable_1, dout_enable_0};
301	  assign dout_valid_s = {dout_valid_7, dout_valid_6, dout_valid_5, dout_valid_4,
302	    dout_valid_3, dout_valid_2, dout_valid_1, dout_valid_0};
303	
304	  generate
305	  if (NUM_OF_CHANNELS >= 8) begin
306	  assign dout_data_s = dout_rdata;
307	  end else begin
308	  assign dout_data_s[(T_DOUT_DATA_WIDTH+1):DATA_WIDTH] = 'd0;
309	  assign dout_data_s[(DATA_WIDTH-1):0] = dout_rdata;
310	  end
311	  endgenerate
312	
313	  assign dout_valid_out_7 = dout_valid[7];
314	  assign dout_valid_out_6 = dout_valid[6];
315	  assign dout_valid_out_5 = dout_valid[5];
316	  assign dout_valid_out_4 = dout_valid[4];
317	  assign dout_valid_out_3 = dout_valid[3];
318	  assign dout_valid_out_2 = dout_valid[2];
319	  assign dout_valid_out_1 = dout_valid[1];
320	  assign dout_valid_out_0 = dout_valid[0];
321	
322	  assign dout_data_7 = dout_data[((DOUT_DATA_WIDTH*8)-1):(DOUT_DATA_WIDTH*7)];
323	  assign dout_data_6 = dout_data[((DOUT_DATA_WIDTH*7)-1):(DOUT_DATA_WIDTH*6)];
324	  assign dout_data_5 = dout_data[((DOUT_DATA_WIDTH*6)-1):(DOUT_DATA_WIDTH*5)];
325	  assign dout_data_4 = dout_data[((DOUT_DATA_WIDTH*5)-1):(DOUT_DATA_WIDTH*4)];
326	  assign dout_data_3 = dout_data[((DOUT_DATA_WIDTH*4)-1):(DOUT_DATA_WIDTH*3)];
327	  assign dout_data_2 = dout_data[((DOUT_DATA_WIDTH*3)-1):(DOUT_DATA_WIDTH*2)];
328	  assign dout_data_1 = dout_data[((DOUT_DATA_WIDTH*2)-1):(DOUT_DATA_WIDTH*1)];
329	  assign dout_data_0 = dout_data[((DOUT_DATA_WIDTH*1)-1):(DOUT_DATA_WIDTH*0)];
330	
331	  always @(posedge dout_clk) begin
332	    if (dout_rst == 1'b1) begin
333	      dout_valid <= 8'd0;
334	    end else begin
335	      dout_valid <= dout_valid_s;
336	    end
337	  end
338	
339	  generate
340	  for (n = 0; n < NUM_OF_CHANNELS; n = n + 1) begin: g_out
341	  always @(posedge dout_clk) begin
342	    if (dout_rst == 1'b1) begin
343	      dout_data[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)] <= 'd0;
344	    end else if (dout_valid_s[n] == 1'b1) begin
345	      dout_data[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)] <=
346	        dout_data_s[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)];
347	    end
348	  end
349	  end
350	  endgenerate
351	
352	  always @(posedge dout_clk) begin
353	    dout_rdata <= dout_rdata_s;
354	  end
355	
356	  assign dout_init_s = (dout_enable == dout_enable_s) ? 1'b0 : 1'b1;
357	
358	  always @(posedge dout_clk) begin
359	    if (dout_rst == 1'b1) begin
360	      dout_enable <= 'd0;
361	      dout_req_t <= 'd0;
362	      dout_init <= 'd0;
363	      dout_raddr <= 'd0;
364	    end else begin
365	      dout_enable <= dout_enable_s;
366	      if (dout_init_s == 1'b1) begin
367	        dout_req_t <= ~dout_req_t;
368	        dout_init <= 1'd1;
369	        dout_raddr <= 'd0;
370	      end else if (dout_valid_s[0] == 1'b1) begin
371	        if (dout_raddr[2:0] == 3'd7) begin
372	          dout_req_t <= ~dout_req_t;
373	          dout_init <= 1'd0;
374	        end
375	        dout_raddr <= dout_raddr + 1'b1;
376	      end
377	    end
378	  end
379	
380	  always @(posedge dout_clk) begin
381	    if (dout_rst == 1'b1) begin
382	      dout_unf_m1 <= 'd0;
383	      dout_unf <= 'd0;
384	    end else begin
385	      dout_unf_m1 <= din_unf_d;
386	      dout_unf <= dout_unf_m1;
387	    end
388	  end
389	
390	  // instantiations
391	
392	  ad_mem #(
393	    .ADDRESS_WIDTH(ADDRESS_WIDTH),
394	    .DATA_WIDTH(DATA_WIDTH)
395	  ) i_mem (
396	    .clka (din_clk),
397	    .wea (din_wr),
398	    .addra (din_waddr),
399	    .dina (din_wdata),
400	    .clkb (dout_clk),
401	    .reb (1'b1),
402	    .addrb (dout_raddr),
403	    .doutb (dout_rdata_s));
404	
405	endmodule
406

