33	// ***************************************************************************
34	// ***************************************************************************
35	
36	`timescale 1ns/100ps
37	
38	module util_wfifo #(
39	
40	  parameter   NUM_OF_CHANNELS = 4,
41	  parameter   DIN_DATA_WIDTH = 32,
42	  parameter   DOUT_DATA_WIDTH = 64,
43	  parameter   DIN_ADDRESS_WIDTH = 8
44	) (
45	
46	  // d-in interface
47	
48	  input                   din_rst,
49	  input                   din_clk,
50	  input                   din_enable_0,
51	  input                   din_valid_0,
52	  input       [DIN_DATA_WIDTH-1:0]  din_data_0,
53	  input                   din_enable_1,
54	  input                   din_valid_1,
55	  input       [DIN_DATA_WIDTH-1:0]  din_data_1,
56	  input                   din_enable_2,
57	  input                   din_valid_2,
58	  input       [DIN_DATA_WIDTH-1:0]  din_data_2,
59	  input                   din_enable_3,
60	  input                   din_valid_3,
61	  input       [DIN_DATA_WIDTH-1:0]  din_data_3,
62	  input                   din_enable_4,
63	  input                   din_valid_4,
64	  input       [DIN_DATA_WIDTH-1:0]  din_data_4,
65	  input                   din_enable_5,
66	  input                   din_valid_5,
67	  input       [DIN_DATA_WIDTH-1:0]  din_data_5,
68	  input                   din_enable_6,
69	  input                   din_valid_6,
70	  input       [DIN_DATA_WIDTH-1:0]  din_data_6,
71	  input                   din_enable_7,
72	  input                   din_valid_7,
73	  input       [DIN_DATA_WIDTH-1:0]  din_data_7,
74	  output  reg             din_ovf,
75	
76	  // d-out interface
77	
78	  input                   dout_rstn,
79	  input                   dout_clk,
80	  output                  dout_enable_0,
81	  output                  dout_valid_0,
82	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_0,
83	  output                  dout_enable_1,
84	  output                  dout_valid_1,
85	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_1,
86	  output                  dout_enable_2,
87	  output                  dout_valid_2,
88	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_2,
89	  output                  dout_enable_3,
90	  output                  dout_valid_3,
91	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_3,
92	  output                  dout_enable_4,
93	  output                  dout_valid_4,
94	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_4,
95	  output                  dout_enable_5,
96	  output                  dout_valid_5,
97	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_5,
98	  output                  dout_enable_6,
99	  output                  dout_valid_6,
100	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_6,
101	  output                  dout_enable_7,
102	  output                  dout_valid_7,
103	  output      [DOUT_DATA_WIDTH-1:0]  dout_data_7,
104	  input                   dout_ovf
105	);
106	
107	  localparam  M_MEM_RATIO = DOUT_DATA_WIDTH/DIN_DATA_WIDTH;
108	  localparam  ADDRESS_WIDTH = (DIN_ADDRESS_WIDTH > 4) ? DIN_ADDRESS_WIDTH : 4;
109	  localparam  DATA_WIDTH = DOUT_DATA_WIDTH * NUM_OF_CHANNELS;
110	  localparam  T_DIN_DATA_WIDTH = DIN_DATA_WIDTH * 8;
111	  localparam  T_DOUT_DATA_WIDTH = DOUT_DATA_WIDTH * 8;
112	
113	  // internal registers
114	
115	  reg     [(DATA_WIDTH-1):0]          din_wdata = 'd0;
116	  reg     [ 7:0]                      din_enable = 'd0;
117	  reg                                 din_wr = 'd0;
118	  reg     [(ADDRESS_WIDTH-1):0]       din_waddr = 'd0;
119	  reg                                 din_req_t = 'd0;
120	  reg     [(ADDRESS_WIDTH-4):0]       din_rinit = 'd0;
121	  reg                                 din_ovf_m1 = 'd0;
122	  reg                                 dout_req_t_m1 = 'd0;
123	  reg                                 dout_req_t_m2 = 'd0;
124	  reg                                 dout_req_t_m3 = 'd0;
125	  reg                                 dout_req_t = 'd0;
126	  reg     [(ADDRESS_WIDTH-4):0]       dout_rinit = 'd0;
127	  reg                                 dout_ovf_d = 'd0;
128	  reg     [ 3:0]                      dout_req_cnt = 'd0;
129	  reg     [(ADDRESS_WIDTH-1):0]       dout_raddr = 'd8;
130	  reg                                 dout_rd_d = 'd0;
131	  reg                                 dout_valid = 'd0;
132	  reg     [ 7:0]                      dout_enable_m1 = 'd0;
133	  reg     [ 7:0]                      dout_enable = 'd0;
134	  reg     [(DATA_WIDTH-1):0]          dout_rdata = 'd0;
135	
136	  // internal signals
137	
138	  wire    [ 7:0]                      din_enable_s;
139	  wire    [ 7:0]                      din_valid_s;
140	  wire    [(T_DIN_DATA_WIDTH-1):0]    din_data_s;
141	  wire                                dout_req_t_s;
142	  wire    [(DATA_WIDTH-1):0]          dout_rdata_s;
143	  wire    [(T_DOUT_DATA_WIDTH+1):0]   dout_data_s;
144	  wire    [ 2:0]                      din_dcnt_s;
145	
146	  // variables
147	
148	  genvar                              n;
149	
150	  // concat signals, valid_0 must always be active
151	
152	  assign din_enable_s = { din_enable_7, din_enable_6, din_enable_5, din_enable_4,
153	                          din_enable_3, din_enable_2, din_enable_1, din_enable_0};
154	  assign din_valid_s  = { din_valid_7,  din_valid_6,  din_valid_5,  din_valid_4,
155	                          din_valid_3,  din_valid_2,  din_valid_1,  din_valid_0};
156	  assign din_data_s   = { din_data_7,   din_data_6,   din_data_5,   din_data_4,
157	                          din_data_3,   din_data_2,   din_data_1,   din_data_0};
158	
159	  // simple data transfer-- no ovf/unf handling- read-bw > write-bw (equal will NOT work)
160	  // dout_width >= din_width only-
161	
162	  generate
163	  for (n = 0; n < NUM_OF_CHANNELS; n = n + 1) begin: g_in
164	  if (M_MEM_RATIO == 1) begin
165	  always @(posedge din_clk) begin
166	    if (din_valid_s[n] == 1'b1) begin
167	      din_wdata[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)] <=
168	        din_data_s[((DIN_DATA_WIDTH*(n+1))-1):(DIN_DATA_WIDTH*n)];
169	    end
170	  end
171	  end else begin
172	  always @(posedge din_clk) begin
173	    if (din_valid_s[n] == 1'b1) begin
174	      din_wdata[((DOUT_DATA_WIDTH*(n+1))-1):(DOUT_DATA_WIDTH*n)] <=
175	        {din_data_s[((DIN_DATA_WIDTH*(n+1))-1):(DIN_DATA_WIDTH*n)],
176	        din_wdata[((DOUT_DATA_WIDTH*(n+1))-1):(DIN_DATA_WIDTH+(DOUT_DATA_WIDTH*n))]};
177	    end
178	  end
179	  end
180	  end
181	  endgenerate
182	
183	  generate
184	  if (M_MEM_RATIO == 1) begin
185	    assign din_dcnt_s = 'b0;
186	  end else begin
187	    reg [ 2:0] din_dcnt = 'd0;
188	
189	    always @(posedge din_clk)
190	    if (din_rst == 1'b1) begin
191	      din_dcnt <= 'd0;
192	    end else begin
193	      if (din_valid_s[0] == 1'b1) begin
194	        din_dcnt <= din_dcnt + 1'b1;
195	      end
196	    end
197	
198	    assign din_dcnt_s = din_dcnt;
199	  end
200	  endgenerate
201	  always @(posedge din_clk) begin
202	    if (din_rst == 1'b1) begin
203	      din_enable <= 8'd0;
204	      din_wr <= 1'd0;
205	      din_waddr <= 'd0;
206	      din_req_t <= 1'd0;
207	      din_rinit <= 'd0;
208	      din_ovf_m1 <= 'd0;
209	      din_ovf <= 'd0;
210	    end else begin
211	      din_enable <= din_enable_s;
212	      case (M_MEM_RATIO)
213	        8: din_wr <= din_valid_s[0] & din_dcnt_s[0] & din_dcnt_s[1] & din_dcnt_s[2];
214	        4: din_wr <= din_valid_s[0] & din_dcnt_s[0] & din_dcnt_s[1];
215	        2: din_wr <= din_valid_s[0] & din_dcnt_s[0];
216	        default: din_wr <= din_valid_s[0];
217	      endcase
218	      if (din_wr == 1'b1) begin
219	        din_waddr <= din_waddr + 1'b1;
220	      end
221	      if ((din_wr == 1'b1) && (din_waddr[2:0] == 3'd7)) begin
222	        din_req_t <= ~din_req_t;
223	        din_rinit <= din_waddr[(ADDRESS_WIDTH-1):3];
224	      end
225	      din_ovf_m1 <= dout_ovf_d;
226	      din_ovf <= din_ovf_m1;
227	    end
228	  end
229	
230	  // read interface (bus expansion and/or clock conversion)
231	
232	  assign dout_req_t_s = dout_req_t_m3 ^ dout_req_t_m2;
233	
234	  always @(posedge dout_clk or negedge dout_rstn) begin
235	    if (dout_rstn == 1'b0) begin
236	      dout_req_t_m1 <= 'd0;
237	      dout_req_t_m2 <= 'd0;
238	      dout_req_t_m3 <= 'd0;
239	      dout_req_t <= 'd0;
240	      dout_rinit <= 'd0;
241	      dout_ovf_d <= 'd0;
242	    end else begin
243	      dout_req_t_m1 <= din_req_t;
244	      dout_req_t_m2 <= dout_req_t_m1;
245	      dout_req_t_m3 <= dout_req_t_m2;
246	      dout_req_t <= dout_req_t_s;
247	      if (dout_req_t_s == 1'b1) begin
248	        dout_rinit <= din_rinit;
249	      end
250	      dout_ovf_d <= dout_ovf;
251	    end
252	  end
253	
254	  always @(posedge dout_clk or negedge dout_rstn) begin
255	    if (dout_rstn == 1'b0) begin
256	      dout_req_cnt <= 'd0;
257	      dout_raddr <= 'd8;
258	      dout_rd_d <= 'd0;
259	      dout_valid <= 'd0;
260	    end else begin
261	      if (dout_req_t == 1'b1) begin
262	        dout_req_cnt <= 4'h8;
263	        dout_raddr <= {dout_rinit, 3'd0};
264	      end else if (dout_req_cnt[3] == 1'b1) begin
265	        dout_req_cnt <= dout_req_cnt + 1'b1;
266	        dout_raddr <= dout_raddr + 1'b1;
267	      end
268	      dout_rd_d <= dout_req_cnt[3];
269	      dout_valid <= dout_rd_d;
270	    end
271	  end
272	
273	  always @(posedge dout_clk or negedge dout_rstn) begin
274	    if (dout_rstn == 1'b0) begin
275	      dout_enable_m1 <= 'd0;
276	      dout_enable <= 'd0;
277	    end else begin
278	      dout_enable_m1 <= din_enable;
279	      dout_enable <= dout_enable_m1;
280	    end
281	  end
282	
283	  always @(posedge dout_clk) begin
284	    dout_rdata <= dout_rdata_s;
285	  end
286	
287	  generate
288	  if (NUM_OF_CHANNELS >= 8) begin
289	  assign dout_data_s = dout_rdata;
290	  end else begin
291	  assign dout_data_s[(T_DOUT_DATA_WIDTH+1):DATA_WIDTH] = 'd0;
292	  assign dout_data_s[(DATA_WIDTH-1):0] = dout_rdata;
293	  end
294	  endgenerate
295	
296	  assign dout_enable_7 = dout_enable[7];
297	  assign dout_valid_7 = dout_valid;
298	  assign dout_data_7 = dout_data_s[((DOUT_DATA_WIDTH*8)-1):(DOUT_DATA_WIDTH*7)];
299	
300	  assign dout_enable_6 = dout_enable[6];
301	  assign dout_valid_6 = dout_valid;
302	  assign dout_data_6 = dout_data_s[((DOUT_DATA_WIDTH*7)-1):(DOUT_DATA_WIDTH*6)];
303	
304	  assign dout_enable_5 = dout_enable[5];
305	  assign dout_valid_5 = dout_valid;
306	  assign dout_data_5 = dout_data_s[((DOUT_DATA_WIDTH*6)-1):(DOUT_DATA_WIDTH*5)];
307	
308	  assign dout_enable_4 = dout_enable[4];
309	  assign dout_valid_4 = dout_valid;
