311	
312	  assign dout_enable_3 = dout_enable[3];
313	  assign dout_valid_3 = dout_valid;
314	  assign dout_data_3 = dout_data_s[((DOUT_DATA_WIDTH*4)-1):(DOUT_DATA_WIDTH*3)];
315	
